    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof repairQueryRun>>, TError,RepairQueryRunMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof repairQueryRun>>, TError,RepairQueryRunMutationVariables, TContext> => {

const mutationKey = getRepairQueryRunMutationKey();
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof repairQueryRun>>, RepairQueryRunMutationVariables> = (props) => {
          const {runId,data} = props ?? {};

          return  repairQueryRun(runId,data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type RepairQueryRunMutationResult = NonNullable<Awaited<ReturnType<typeof repairQueryRun>>>
    export type RepairQueryRunMutationBody = BodyType<RepairRunInput>
    export type RepairQueryRunMutationError = ErrorType<ErrorResponse>
    export type RepairQueryRunMutationVariables = {runId: string;data: BodyType<RepairRunInput>}

